<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { TabBarContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
import {tabBarPaths} from './tab-bar-icons.js';let p: TabBarContract & {icons?:Readonly<Record<string,Snippet>>} = $props();const uid=$props.id();function validate(){for(const item of p.items)for(const icon of[item.icon,item.currentIcon].filter(Boolean))if(icon&&!Object.hasOwn(tabBarPaths,icon)&&!p.icons?.[icon])throw new TypeError(`Unknown TabBar icon: ${icon}; supply a native icons snippet`);}validate();$effect(validate);$effect(()=>{if(p.items.length+(p.menuAction?1:0)>5)throw new RangeError('Tab bar supports at most five items');});

</script>
<nav aria-label="하단 탐색" {...owned('tab-bar','root','current')}><ul {...owned('tab-bar','list')}>{#each p.items as item(item.id)}{@const icon=p.currentId===item.id?(item.currentIcon??item.icon):item.icon}<li {...owned('tab-bar','item',p.currentId===item.id&&'current')}><a aria-label={item.badge!==undefined?`${item.label}${item.badge}`:item.label} href={item.href} aria-current={p.currentId===item.id?'page':undefined} {...owned('tab-bar','link')}><span aria-hidden="true" {...owned('tab-bar','icon')}>{#if p.icons?.[icon]}{@render p.icons[icon]()}{:else}<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width={p.currentId===item.id?2:1.5}><path d={tabBarPaths[icon as keyof typeof tabBarPaths]}/></svg>{/if}</span>{#if p.currentId===item.id}<span aria-hidden="true" {...owned('tab-bar','indicator','current')}><svg width="8" height="8" viewBox="0 0 8 8"><circle cx="4" cy="4" r="3" fill="currentColor"/></svg></span>{/if}<span {...owned('tab-bar','label')}>{item.label}</span>{#if item.badge!==undefined}<span id={`${uid}-${item.id}-badge`} {...owned('tab-bar','badge')}>{item.badge}</span>{/if}</a></li>{/each}{#if p.menuAction}<li><button type="button" {...owned('tab-bar','menu-trigger')} onclick={()=>p.menuAction?.onRequest()}>{p.menuAction.label}</button></li>{/if}</ul></nav>
